import json, pyarrow.parquet as pq
from pathlib import Path
from collections import defaultdict
train=pq.read_table("/workspace/taco_verl/train.parquet").to_pylist()
meta={}
for tr in train:
    io=json.loads(tr["reward_model"]["ground_truth"])
    def slen(x):
        if isinstance(x, list):
            return sum(len(str(y)) for y in x)
        return len(str(x))
    max_in=max(slen(x) for x in io["inputs"])
    max_out=max(slen(x) for x in io["outputs"])
    total=sum(slen(x)+slen(y) for x,y in zip(io["inputs"], io["outputs"]))
    meta[tr["prompt"][0]["content"]]={"n":tr["extra_info"]["n_tests"], "max_in":max_in, "max_out":max_out, "total":total, "pid":tr["extra_info"]["problem_id"]}

def body_of(inp):
    body=inp
    if body.startswith("user\n"): body=body[5:]
    if body.endswith("\nassistant\n"): body=body[:-len("\nassistant\n")]
    return body

agg=defaultdict(lambda: {"n":0,"solved":0,"pr":0.0})
for fp in Path("/workspace/rollout_data").glob("*.jsonl"):
    if not fp.stem.isdigit(): continue
    for line in fp.open():
        r=json.loads(line)
        b=body_of(r["input"])
        a=agg[b]
        a["n"]+=1
        a["solved"] += 1 if (r.get("score") or 0)==1 else 0
        a["pr"] += r.get("pass_rate") or 0

rows=[]
for b,a in agg.items():
    m=meta[b]
    rows.append((m["max_in"], m["n"], a["solved"]>0, a["solved"]/a["n"], a["pr"]/a["n"], m["total"], m["max_out"]))

def bucket_report(name, pred):
    sub=[r for r in rows if pred(r)]
    if not sub:
        print(name, 0); return
    ever=sum(1 for r in sub if r[2])
    print(f"{name}: n={len(sub)} ever={ever} ({ever/len(sub):.2f}) mean_acc={sum(r[3] for r in sub)/len(sub):.3f} mean_pr={sum(r[4] for r in sub)/len(sub):.3f}")

for lo,hi in [(0,200),(201,1000),(1001,5000),(5001,20000),(20001,10**9)]:
    bucket_report(f"max_in {lo}-{hi}", lambda r,lo=lo,hi=hi: lo<=r[0]<=hi)

print("--- n_tests 1 by input size ---")
for lo,hi in [(0,200),(201,2000),(2001,10**9)]:
    bucket_report(f"n=1 max_in {lo}-{hi}", lambda r,lo=lo,hi=hi: r[1]==1 and lo<=r[0]<=hi)

print("--- n_tests 2-20 by input size ---")
for lo,hi in [(0,500),(501,5000),(5001,10**9)]:
    bucket_report(f"n2-20 max_in {lo}-{hi}", lambda r,lo=lo,hi=hi: 2<=r[1]<=20 and lo<=r[0]<=hi)

# whole train distribution not just seen
print("\nFULL TRAIN size dist")
allrows=[]
for tr in train:
    io=json.loads(tr["reward_model"]["ground_truth"])
    def slen(x):
        if isinstance(x, list): return sum(len(str(y)) for y in x)
        return len(str(x))
    allrows.append(max(slen(x) for x in io["inputs"]))
for lo,hi in [(0,200),(201,1000),(1001,5000),(5001,20000),(20001,10**9)]:
    c=sum(1 for x in allrows if lo<=x<=hi)
    print(lo,hi,c)
print("train max_in median", sorted(allrows)[len(allrows)//2], "p90", sorted(allrows)[int(len(allrows)*0.9)], "max", max(allrows))
